                     <th className="px-4 py-3">Rate</th>
                     <th className="px-4 py-3 text-center">Regular (1x)</th>
                     <th className="px-4 py-3 text-center">OT (1.25x)</th>
                     <th className="px-4 py-3 text-center">Extra (1.5x)</th>
